package id.walt.verifier2.mdocs

/**
 * Shared mDL test fixture, extracted so the DC API round trip and the cross-device mdoc test verify
 * the same issuer-signed credential. A DC API failure is then attributable to the DC API path.
 *
 * [HOLDER_JWK] is the `deviceKey` embedded in this fixture's MSO - `device_key_auth` fails if the two
 * drift apart. Its `kid` is that key's RFC 7638 thumbprint. Both tests share it, so it exists once
 * here rather than once per test; [HOLDER_SERIALIZED_KEY] is the same key in the envelope the crypto
 * v1 `KeyManager` takes, while the DC API test feeds [HOLDER_JWK] to crypto2 directly.
 *
 * ## Expiry
 *
 * This fixture is time-limited and will start failing on its own:
 * - the document signer in [MDL_FIXTURE_X5C] is valid until **2026-09-02**
 * - the MSO's `validUntil` is **2026-09-11**
 *
 * `mso_mdoc/issuer_auth` checks the DS certificate against the session's verification time, and that
 * time is not injectable through the HTTP API (`VerificationSessionContext.verificationTime` defaults
 * to `Clock.System.now()`), so these tests cannot pin a clock and must be re-signed before then.
 *
 * Unlike the deployed demo issuer's document signer - X.509 v1 with no extensions, see
 * `DeployedIssuerDocumentSignerTest` - this one is a conformant ISO 18013-5 signer
 * (`keyUsage:digitalSignature`, EKU `1.0.18013.5.1.2`), which is why `issuer_auth` passes here.
 * Keep that property when regenerating it, or these tests stop covering issuer authentication.
 */
internal const val MDL_FIXTURE_SIGNED_HEX: String =
    ""

internal const val MDL_FIXTURE_X5C: String =
    ""

internal const val MDL_FIXTURE_SIGNER_JWK: String =
    """{"type":"jwk","jwk":{"kty":"EC","crv":"P-256","x":"Pzp6eVSAdXERqAp8q8OuDEhl2ILGAaoaQXTJ2sD2g5U","y":"6dwhUAzKzKUf0kNI7f40zqhMZNT0c40O_WiqSLCTNZo"}}"""

internal const val HOLDER_JWK: String =
    """{
      "kty": "EC",
      "d": "QN9Y3k_3Hy2OV0C5Pmez_ObEXJKcXonnMg3xTpcLOAg",
      "crv": "P-256",
      "kid": "KmQ8TOSmhg1UV9nQfQaTQ5wwbHrEgOENvJ_3AlEriAw",
      "x": "eTT2WdzlmOWBItdgSmsqB1_BP69wfuwOe1IYvaY1WdI",
      "y": "wbOu3GP02JiOVIRQ_ufWLRNOmDB6seYAabCmsGBfr_4"
    }"""

/** [HOLDER_JWK] in the envelope `KeyManager.resolveSerializedKey` expects, for the crypto v1 callers. */
internal const val HOLDER_SERIALIZED_KEY: String =
    """{"type":"jwk","jwk":""" + HOLDER_JWK + "}"
